try:
    def _cap(s, n):
        s = str(s or '')
        return s if len(s) <= n else s[:n] + '\n\n[... truncated %d chars]' % (len(s) - n)
    api_rec = env['mcp.api.key'].sudo().search([('name', '=', 'anthropic-api')], limit=1)
    if not api_rec or not api_rec.api_key:
        result = {'error': 'Anthropic API key not configured. Create an mcp.api.key record named anthropic-api.'}
    else:
        mcp_rec = env['mcp.api.key'].sudo().search([('name', '=', 'claude-bot')], limit=1)
