        use_thinking = body.get('thinking', False)
        use_mcp = body.get('mcp_enabled', True)
        use_web = body.get('web_search', False)
        use_code = body.get('code_exec', True)
        if use_mcp and (not mcp_rec or not mcp_rec.api_key):
            raise Exception('MCP tools are enabled but the claude-bot API key is not configured. Create an mcp.api.key record named "claude-bot", or disable the MCP toggle in chat settings.')
        system_prompt = body.get('system_prompt', '')
        container_id = body.get('container_id')
        full_system = system_prompt or ''
        if use_code:
            code_instructions = '\n\nIMPORTANT: When you create, modify, or generate files that the user may want to download, ALWAYS copy the final file to the $OUTPUT_DIR directory (e.g. `cp /tmp/result.csv $OUTPUT_DIR/result.csv`). Files placed in $OUTPUT_DIR are automatically made available for download in the UI. Do NOT provide raw file paths — the app handles download buttons automatically for any files in $OUTPUT_DIR.'
            full_system = (full_system + code_instructions) if full_system else code_instructions.strip()
        payload = {'model': mdl, 'max_tokens': 16000, 'messages': msgs, 'cache_control': {'type': 'ephemeral'}}
        if full_system:
            payload['system'] = [{'type': 'text', 'text': full_system, 'cache_control': {'type': 'ephemeral'}}]
        is_adaptive_model = mdl.startswith('claude-opus-4-7')
        if is_adaptive_model:
            payload['max_tokens'] = 32000
        if use_thinking:
            if is_adaptive_model:
                payload['thinking'] = {'type': 'adaptive', 'display': 'summarized'}
                payload['output_config'] = {'effort': 'high'}
                payload['max_tokens'] = 64000
            else:
                payload['thinking'] = {'type': 'enabled', 'budget_tokens': 10000}
                payload['max_tokens'] = 32000
        if container_id and use_code:
            payload['container'] = container_id
        cm_models = ('claude-opus-4-6', 'claude-sonnet-4-6', 'claude-opus-4-7')
        tools = []
        if use_mcp and mcp_rec and mcp_rec.api_key:
            payload['mcp_servers'] = [{'type': 'url', 'url': base_url + '/' + db_name + '/mcp', 'name': 'odoo', 'authorization_token': mcp_rec.api_key}]
            tools.append({'type': 'mcp_toolset', 'mcp_server_name': 'odoo'})
        if use_web:
            ws_type = 'web_search_20260209' if mdl in cm_models else 'web_search_20250305'
            wf_type = 'web_fetch_20260209' if mdl in cm_models else 'web_fetch_20250910'
            tools.append({'type': ws_type, 'name': 'web_search', 'max_uses': 10})
            tools.append({'type': wf_type, 'name': 'web_fetch', 'max_uses': 10})
        if use_code and not (use_web and mdl in cm_models):
            tools.append({'type': 'code_execution_20250825', 'name': 'code_execution'})
        if tools:
            payload['tools'] = tools
        cm_edits = []
        if use_thinking and mdl in cm_models:
            cm_edits.append({'type': 'clear_thinking_20251015', 'keep': {'type': 'thinking_turns', 'value': 2}})
        if tools and mdl in cm_models:
            cm_edits.append({'type': 'clear_tool_uses_20250919', 'trigger': {'type': 'input_tokens', 'value': 80000}, 'keep': {'type': 'tool_uses', 'value': 8}, 'clear_at_least': {'type': 'input_tokens', 'value': 20000}})
        if mdl in cm_models:
            cm_edits.append({'type': 'compact_20260112', 'trigger': {'type': 'input_tokens', 'value': 100000}})
        if cm_edits:
            payload['context_management'] = {'edits': cm_edits}
        betas = []
        if mdl in cm_models:
            betas.extend(['compact-2026-01-12', 'context-management-2025-06-27'])
        if use_mcp and mcp_rec and mcp_rec.api_key:
            betas.append('mcp-client-2025-11-20')
        has_files = False
        for m in msgs:
            mc = m.get('content', '')
            if isinstance(mc, list):
                for b in mc:
                    if isinstance(b, dict) and (((b.get('source') or {}).get('type') == 'file') or b.get('type') == 'container_upload'):
                        has_files = True
                        break
            if has_files:
                break
        if has_files or use_code:
            betas.append('files-api-2025-04-14')
        headers = {
            'x-api-key': api_rec.api_key,
            'anthropic-version': '2023-06-01',
            'content-type': 'application/json',
        }
        if betas:
            headers['anthropic-beta'] = ','.join(betas)
        resp = requests.post(
