        if not isinstance(data, dict):
            raise Exception('Anthropic API returned unexpected response shape (HTTP %s)' % resp.status_code)
        err = data.get('error')
        if err:
            msg = err.get('message', str(err)) if isinstance(err, dict) else str(err)
            result = {'role': 'assistant', 'content': '', 'error': msg}
        else:
            content_blocks = []
            thinking_parts = []
            for block in (data.get('content') or []):
                if not isinstance(block, dict):
                    continue
                btype = block.get('type', '')
                if btype == 'thinking':
                    thinking_parts.append(block.get('thinking', ''))
                elif btype == 'compaction':
                    content_blocks.append({'type': 'compaction', 'content': block.get('content', '')})
                elif btype == 'text':
                    tb = {'type': 'text', 'text': block['text']}
                    citations = []
                    for c in (block.get('citations') or []):
                        if isinstance(c, dict):
                            citations.append({'url': c.get('url', ''), 'title': c.get('title', ''), 'cited_text': c.get('cited_text', '')})
                    if citations:
                        tb['citations'] = citations
                    content_blocks.append(tb)
                elif btype == 'mcp_tool_use':
                    content_blocks.append({'type': 'tool_call', 'name': block.get('name', ''), 'input': block.get('input', {}), 'server': block.get('server_name', 'odoo')})
                elif btype == 'mcp_tool_result':
                    sub = block.get('content') or []
                    txt = ''
                    if isinstance(sub, list):
                        texts = [c.get('text', '') for c in sub if isinstance(c, dict) and c.get('type') == 'text']
                        txt = texts[0] if texts else json.dumps(sub, indent=2, default=str)
                    else:
                        txt = str(sub)
                    content_blocks.append({'type': 'tool_result', 'content': _cap(txt, 300000), 'is_error': block.get('is_error', False)})
                elif btype == 'server_tool_use':
                    name = block.get('name', '')
                    inp = block.get('input') or {}
                    bid = block.get('id', '')
                    if name == 'web_search':
                        content_blocks.append({'type': 'web_search', 'query': inp.get('query', ''), 'id': bid})
                    elif name == 'web_fetch':
                        content_blocks.append({'type': 'web_fetch', 'url': inp.get('url', ''), 'id': bid})
                    elif name == 'bash_code_execution':
                        content_blocks.append({'type': 'code_exec', 'command': inp.get('command', ''), 'id': bid})
                    elif name == 'text_editor_code_execution':
                        content_blocks.append({'type': 'file_editor', 'command': inp.get('command', ''), 'path': inp.get('path', ''), 'file_text': inp.get('file_text', ''), 'id': bid})
                    else:
                        content_blocks.append({'type': 'server_tool', 'name': name, 'input': inp, 'id': bid})
                elif btype == 'web_search_tool_result':
                    results = []
                    for r in (block.get('content') or []):
                        if isinstance(r, dict) and r.get('type') == 'web_search_result':
                            results.append({'title': r.get('title', ''), 'url': r.get('url', ''), 'page_age': r.get('page_age', '')})
                    content_blocks.append({'type': 'web_search_results', 'results': results})
                elif btype == 'web_fetch_tool_result':
                    wfc = block.get('content', {})
                    if isinstance(wfc, dict) and wfc.get('type') == 'web_fetch_result':
                        url = wfc.get('url', '')
                        doc = wfc.get('content', {})
                        preview = ''
                        if isinstance(doc, dict):
                            src = doc.get('source') or {}
                            if isinstance(src, dict) and src.get('type') == 'text':
                                preview = (src.get('data') or '')[:500]
                        content_blocks.append({'type': 'web_fetch_result', 'url': url, 'content_preview': preview})
                    elif isinstance(wfc, dict) and wfc.get('type') == 'web_fetch_tool_error':
                        content_blocks.append({'type': 'web_fetch_result', 'url': '', 'error': wfc.get('error_code', 'unknown')})
                    else:
                        content_blocks.append({'type': 'web_fetch_result', 'url': '', 'content_preview': str(wfc)[:500]})
                elif btype == 'bash_code_execution_tool_result':
                    c = block.get('content', {})
                    if isinstance(c, dict) and c.get('type') == 'bash_code_execution_result':
                        files_out = []
                        for f in (c.get('content') or []):
                            if isinstance(f, dict) and f.get('file_id'):
                                files_out.append({'file_id': f['file_id'], 'filename': f.get('filename', 'download')})
                        block_data = {
                            'type': 'code_exec_result',
                            'stdout': _cap(c.get('stdout'), 500000),
                            'stderr': _cap(c.get('stderr'), 100000),
                            'return_code': c.get('return_code', -1),
                        }
                        if files_out:
                            block_data['files'] = files_out
                        content_blocks.append(block_data)
                    elif isinstance(c, dict) and c.get('type') == 'bash_code_execution_tool_result_error':
                        content_blocks.append({'type': 'code_exec_result', 'stdout': '', 'stderr': c.get('error_code', 'error'), 'return_code': 1})
                    else:
                        content_blocks.append({'type': 'code_exec_result', 'stdout': _cap(c, 100000), 'stderr': '', 'return_code': 0})
                elif btype == 'text_editor_code_execution_tool_result':
                    c = block.get('content', {})
                    if isinstance(c, dict):
                        content_blocks.append({
                            'type': 'file_editor_result',
                            'content': _cap(c.get('content') or json.dumps(c, default=str), 300000),
                            'file_type': c.get('file_type', ''),
                            'is_update': c.get('is_file_update', False),
                        })
                    else:
